#include <bits/stdc++.h>
using namespace std;

int solve(int a, int b) {
    queue<pair<pair<int, int>, int>> q;
    set<pair<int, int>> visited;

    q.push({{a, b}, 0});
    visited.insert({a, b});

    while (!q.empty()) {
        auto node = q.front();
        q.pop();

        int x = node.first.first;
        int y = node.first.second;
        int distance = node.second;

        if (x == y)
            return distance;

        vector<pair<int, int>> nextStates;

        if (x % 2 == 0) nextStates.push_back({x / 2, y});
        if (x % 3 == 0) nextStates.push_back({x / 3, y});
        if (x % 5 == 0) nextStates.push_back({x / 5, y});
        if (y % 2 == 0) nextStates.push_back({x, y / 2});
        if (y % 3 == 0) nextStates.push_back({x, y / 3});
        if (y % 5 == 0) nextStates.push_back({x, y / 5});

        for (const auto& state : nextStates) {
            if (visited.insert(state).second)
                q.push({state, distance + 1});
        }
    }

    return -1;
}

int main() {
    int x, y;
    scanf("%d %d", &x, &y);
    cout << solve(x, y) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int solve(int a, int b) {
    if (a == 0 || b == 0)
        return a == b ? 0 : -1;

    int operations = 0;

    for (int p : {2, 3, 5}) {
        int countA = 0, countB = 0;

        while (a % p == 0) {
            a /= p;
            ++countA;
        }
        while (b % p == 0) {
            b /= p;
            ++countB;
        }

        operations += abs(countA - countB);
    }

    return a == b ? operations : -1;
}

int main() {
    int x, y;
    scanf("%d %d", &x, &y);
    cout << solve(x, y) << '\n';
    return 0;
}

