using namespace std;

int solve(int a, int b) {
    queue<tuple<int, int, int>> q;
    set<pair<int, int>> visited;

    q.emplace(a, b, 0);
    visited.emplace(a, b);

    while (!q.empty()) {
        auto [x, y, steps] = q.front();
        q.pop();

        if (x == y) return steps;

        for (int d : {2, 3, 5}) {
            if (x % d == 0 && visited.emplace(x / d, y).second)
                q.emplace(x / d, y, steps + 1);

            if (y % d == 0 && visited.emplace(x, y / d).second)
                q.emplace(x, y / d, steps + 1);
        }
    }

    return -1;
}

